mapper.select:
SELECT * FROM (
    SELECT ROWNUM AS rn, a.* FROM (
        SELECT 
            FLIGHT_ID, 
            START_TIME, 
            END_TIME, 
            FLIGHT_DURATION, 
            BATTERY_CONSUMPTION, 
            FLIGHT_DATE, 
            DRONE_ID
        FROM FLIGHT_HISTORY

        /* 최근 비행 내역이 가장 위로 오도록 역순 정렬 */
        ORDER BY FLIGHT_ID DESC
    ) a WHERE ROWNUM <= #{endRow}
) WHERE rn >= #{startRow}
